def has_pair_with_difference(nums, d):
    i, j = 0, 1
    while j < len(nums):
        if i == j:
            j += 1
            continue
        gap = nums[j] - nums[i]
        if gap == d:
            return True
        if gap < d:
            j += 1
        else:
            i += 1
    return False

def longest_k_distinct(s, k):
    counts = {}
    left = best = 0
    for right, ch in enumerate(s):
        counts[ch] = counts.get(ch, 0) + 1
        while len(counts) > k:
            out = s[left]
            counts[out] -= 1
            if counts[out] == 0:
                del counts[out]
            left += 1
        best = max(best, right - left + 1)
    return best

def max_subarray(xs):
    best = (0, 1, xs[0])
    start, run = 0, 0
    for j, x in enumerate(xs):
        if run <= 0:
            start, run = j, x
        else:
            run += x
        if run > best[2]:
            best = (start, j + 1, run)
    return best

